import 'package:flutter/material.dart';
import 'package:flutter_localizations/flutter_localizations.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import 'package:quizaipro_mobile/core/di/providers.dart';
import 'package:quizaipro_mobile/core/router/app_router.dart';
import 'package:quizaipro_mobile/core/theme/aurora_theme.dart';

// Generated by flutter gen-l10n (flutter pub get && flutter build).
// Run: flutter gen-l10n
import 'package:quizaipro_mobile/l10n/app_localizations.dart';

class App extends ConsumerWidget {
  const App({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final router = ref.watch(appRouterProvider);
    final themeMode = ref.watch(themeModeProvider);
    final languageCode = ref.watch(languageCodeProvider);

    return MaterialApp.router(
      title: 'QuizAIPro',
      debugShowCheckedModeBanner: false,

      // ── Routing ──────────────────────────────────────────────────────────
      routerConfig: router,

      // ── Themes ───────────────────────────────────────────────────────────
      theme: AuroraTheme.light(),
      darkTheme: AuroraTheme.dark(),
      themeMode: themeMode,

      // ── Localisation ─────────────────────────────────────────────────────
      localizationsDelegates: const [
        AppLocalizations.delegate,
        GlobalMaterialLocalizations.delegate,
        GlobalWidgetsLocalizations.delegate,
        GlobalCupertinoLocalizations.delegate,
      ],
      supportedLocales: const [
        Locale('en'),
        Locale('ru'),
        Locale('uz'),
      ],
      locale: _resolveLocale(languageCode),
    );
  }

  Locale? _resolveLocale(String code) {
    return switch (code) {
      'en' => const Locale('en'),
      'ru' => const Locale('ru'),
      'uz' => const Locale('uz'),
      _ => null, // system default
    };
  }
}
